create or replace function private.get_account_lifecycle() returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare actor uuid:=private.lifecycle_identity(); l private.account_lifecycle; consents jsonb;
begin
 select * into strict l from private.account_lifecycle where parent_id=actor;
 select coalesce(jsonb_agg(jsonb_build_object('profileId',child_id,'grantedAt',granted_at,'withdrawnAt',withdrawn_at,'method',method) order by granted_at),'[]'::jsonb)
 into consents from private.child_profile_consents where parent_id=actor and l.state='active';
 return jsonb_build_object('state',l.state,'termsVersion','2026-11-22','privacyVersion','2026-11-23',
 'acceptedTermsVersion',l.terms_version,'shownPrivacyVersion',l.privacy_version,'lastActivityAt',case when l.state='active' then l.last_activity_at end,
 'deletionDeadline',l.deletion_deadline,'consents',consents);
end $$;

create or replace function private.complete_parent_onboarding(p_terms_version text,p_privacy_version text,p_parent_declaration boolean,p_accept_terms boolean,p_channel text default 'otp') returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare actor uuid:=private.lifecycle_identity(); t timestamptz:=private.lifecycle_now(); channel text; l private.account_lifecycle;
begin
 if p_terms_version is distinct from '2026-11-22' or p_privacy_version is distinct from '2026-11-23' then raise exception 'document_version_changed' using errcode='22023'; end if;
 if p_parent_declaration is distinct from true or p_accept_terms is distinct from true then raise exception 'Adult guardian declaration and terms acceptance required' using errcode='22023'; end if;
 select * into strict l from private.account_lifecycle where parent_id=actor for update;
 t:=private.lifecycle_now();
 if l.state not in ('onboarding','active') then raise exception 'account_blocked' using errcode='42501'; end if;
 -- Channel is evidence from a signed Auth claim, never a browser assertion.
 channel:=case when exists(select 1 from jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a where a->>'method'='oauth') then 'google'
 when exists(select 1 from jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a where a->>'method'='otp') then 'otp' else 'other' end;
 insert into private.parent_acceptances(parent_id,terms_version,privacy_version,terms_sha256,privacy_sha256,accepted_at,signup_channel,parent_declaration)
 values(actor,p_terms_version,p_privacy_version,(select sha256 from private.legal_document_versions where kind='terms' and version=p_terms_version),(select sha256 from private.legal_document_versions where kind='privacy' and version=p_privacy_version),t,channel,true) on conflict(parent_id,terms_version) do nothing;
 update private.account_lifecycle set state='active',terms_version=p_terms_version,privacy_version=p_privacy_version,accepted_at=coalesce(accepted_at,t),parent_declaration=true,signup_channel=coalesce(signup_channel,channel),last_activity_at=coalesce(last_activity_at,t) where parent_id=actor;
 if l.state='onboarding' then insert into private.lifecycle_outbox(parent_id,kind,dedupe_key) values(actor,'welcome','welcome:'||actor::text) on conflict do nothing; end if;
 return private.get_account_lifecycle();
end $$;

create or replace function private.consent_child_profile(p_child_id text,p_consent boolean,p_guardian_declaration boolean default false) returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare actor uuid:=private.lifecycle_identity(); t timestamptz:=private.lifecycle_now(); children jsonb; active text; d public.family_documents;
begin
 perform 1 from private.account_lifecycle where parent_id=actor and state='active' and terms_version='2026-11-22' and (not (select inactivity_enabled from private.lifecycle_controls) or private.lifecycle_now()<greatest(last_activity_at+interval '90 days',transition_deadline)) for update;
 if not found then raise exception 'account_blocked' using errcode='42501'; end if;
 t:=private.lifecycle_now();
 if not private.family_access_allowed(actor) then raise exception 'account_blocked' using errcode='42501'; end if;
 if p_child_id is null or p_child_id!~'^[a-zA-Z0-9_-]{1,80}$' or p_child_id in ('__proto__','prototype','constructor') or p_consent is null then raise exception 'Invalid profile consent' using errcode='22023'; end if;
 if p_consent then
  if p_guardian_declaration is distinct from true then raise exception 'Guardian declaration required' using errcode='22023'; end if;
  if exists(select 1 from private.child_profile_consents where parent_id=actor and child_id=p_child_id and withdrawn_at is not null) then raise exception 'profile_consent_revoked' using errcode='42501'; end if;
  if not exists(select 1 from private.child_profile_consents where parent_id=actor and child_id=p_child_id) and (select count(*) from private.child_profile_consents where parent_id=actor and withdrawn_at is null)>=5 then raise exception 'At most five online profiles' using errcode='22023'; end if;
  insert into private.child_profile_consents(parent_id,child_id,granted_at,privacy_version,guardian_declaration) values(actor,p_child_id,t,'2026-11-23',true) on conflict do nothing;
 else
  update private.child_profile_consents set withdrawn_at=coalesce(withdrawn_at,t) where parent_id=actor and child_id=p_child_id;
  if not found then raise exception 'Unknown profile consent' using errcode='22023'; end if;
  select * into d from public.family_documents where parent_id=actor for update;
  if found then
   select coalesce(jsonb_agg(child order by n),'[]'::jsonb) into children from jsonb_array_elements(d.snapshot#>'{family,children}') with ordinality c(child,n) where child->>'id'<>p_child_id;
   active:=d.snapshot#>>'{family,activeId}'; if active=p_child_id then active:=coalesce(children->0->>'id',''); end if;
   update public.family_documents set snapshot=jsonb_set(jsonb_set(jsonb_set(d.snapshot,'{family,children}',children),'{family,activeId}',to_jsonb(active)),'{data}',(d.snapshot->'data')-p_child_id),revision=revision+1,updated_at=t where parent_id=actor;
  end if;
 end if;
 update private.account_lifecycle set last_activity_at=greatest(last_activity_at,t) where parent_id=actor;
 update private.lifecycle_outbox set state='cancelled' where parent_id=actor and kind in ('inactivity_14','inactivity_3') and state in ('pending','working');
 return private.get_account_lifecycle();
end $$;

-- The existing public wrappers are SECURITY INVOKER. Their authenticated
-- caller needs EXECUTE on these self-authorizing private function bodies.
-- Keep anon/PUBLIC/service_role denied and preserve that authenticated path.
revoke all on function private.get_account_lifecycle() from public,anon,authenticated,service_role;
revoke all on function private.complete_parent_onboarding(text,text,boolean,boolean,text) from public,anon,authenticated,service_role;
revoke all on function private.consent_child_profile(text,boolean,boolean) from public,anon,authenticated,service_role;
grant execute on function private.get_account_lifecycle() to authenticated;
grant execute on function private.complete_parent_onboarding(text,text,boolean,boolean,text) to authenticated;
grant execute on function private.consent_child_profile(text,boolean,boolean) to authenticated;

create or replace function private.begin_parent_registration(p_nonce_hash text,p_channel text,p_email_hash text,p_terms_version text,p_privacy_version text,p_parent_declaration boolean,p_accept_terms boolean)
returns jsonb language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare t timestamptz; existing private.parent_registration_proofs;
begin
 if p_nonce_hash is null or p_nonce_hash!~'^[a-f0-9]{64}$' or p_channel is null or p_channel not in ('otp','google')
 or (p_channel='otp' and (p_email_hash is null or p_email_hash!~'^[a-f0-9]{64}$'))
 or (p_channel='google' and p_email_hash is not null)
 or p_parent_declaration is distinct from true or p_accept_terms is distinct from true then raise exception 'Invalid registration declaration' using errcode='22023'; end if;
 if p_terms_version is distinct from '2026-11-22' or p_privacy_version is distinct from '2026-11-23' then raise exception 'document_version_changed' using errcode='22023'; end if;
 -- Serialize admissions so concurrent anonymous requests cannot exceed caps.
 perform pg_advisory_xact_lock(726114922098231);
 perform private.cleanup_parent_registrations();
 t:=private.lifecycle_now();
 select * into existing from private.parent_registration_proofs where nonce_hash=p_nonce_hash;
 if found then
  if existing.channel<>p_channel or existing.email_hash is distinct from p_email_hash or existing.terms_version<>p_terms_version or existing.privacy_version<>p_privacy_version then raise exception 'Invalid registration declaration' using errcode='22023'; end if;
  return jsonb_build_object('expiresAt',existing.expires_at);
 end if;
 if (select count(*) from private.parent_registration_proofs)>=1000
 or (select count(*) from private.parent_registration_proofs where declared_at>t-interval '1 minute')>=100
 or (p_email_hash is not null and (select count(*) from private.parent_registration_proofs where email_hash=p_email_hash)>=5)
 then raise exception 'registration_rate_limited' using errcode='P0001'; end if;
 insert into private.parent_registration_proofs(nonce_hash,channel,email_hash,terms_version,privacy_version,parent_declaration,accept_terms,declared_at,expires_at)
 values(p_nonce_hash,p_channel,p_email_hash,p_terms_version,p_privacy_version,true,true,t,t+interval '30 minutes');
 return jsonb_build_object('expiresAt',t+interval '30 minutes');
end $$;

create or replace function private.complete_parent_registration(p_nonce_hash text,p_channel text) returns jsonb
language plpgsql security definer set search_path='' set timezone='UTC' as $$
declare actor uuid:=private.require_fresh_parent(); proof private.parent_registration_proofs; l private.account_lifecycle;
 t timestamptz; actor_hash text; expected_email_hash text; verified_at timestamptz; result jsonb; had_acceptance boolean;
begin
 if p_nonce_hash is null or p_nonce_hash!~'^[a-f0-9]{64}$' or p_channel is null or p_channel not in ('otp','google') then raise exception 'Invalid registration proof' using errcode='22023'; end if;
 select * into strict l from private.account_lifecycle where parent_id=actor for update;
 if l.state in ('deletion_pending','deleting') then return jsonb_build_object('completed',false); end if;
 select * into proof from private.parent_registration_proofs where nonce_hash=p_nonce_hash for update;
 t:=private.lifecycle_now();
 if not found or proof.expires_at<=t or proof.channel<>p_channel then return jsonb_build_object('completed',false); end if;
 actor_hash:=encode(sha256(convert_to(actor::text,'UTF8')),'hex');
 if proof.consumed_at is not null then return jsonb_build_object('completed',proof.consumed_parent_hash=actor_hash and l.state='active' and l.terms_version='2026-11-22'); end if;
 if proof.terms_version<>'2026-11-22' or proof.privacy_version<>'2026-11-23' then return jsonb_build_object('completed',false); end if;
 select max(to_timestamp((a->>'timestamp')::double precision)) into verified_at from jsonb_array_elements(coalesce(auth.jwt()->'amr','[]'::jsonb)) a
 where a->>'method'=case when p_channel='google' then 'oauth' else 'otp' end and a->>'timestamp' ~ '^[0-9]{1,12}(\.[0-9]{1,6})?$';
 if verified_at is null or verified_at<t-interval '5 minutes' or verified_at<proof.declared_at-interval '1 minute' or verified_at>t+interval '1 minute' then return jsonb_build_object('completed',false); end if;
 if p_channel='otp' then
  select encode(sha256(convert_to(lower(btrim(email)),'UTF8')),'hex') into expected_email_hash from auth.users where id=actor;
  if expected_email_hash is distinct from proof.email_hash then return jsonb_build_object('completed',false); end if;
 end if;
 -- Already-complete accounts keep their original evidence, including an older
 -- informational privacy version. Signing in does not demand a new declaration.
 if l.state='active' and l.terms_version='2026-11-22' then
  result:=private.get_account_lifecycle();
 else
  select exists(select 1 from private.parent_acceptances where parent_id=actor and terms_version=proof.terms_version) into had_acceptance;
  result:=private.complete_parent_onboarding(proof.terms_version,proof.privacy_version,proof.parent_declaration,proof.accept_terms,p_channel);
  if not had_acceptance then update private.parent_acceptances set registration_declared_at=proof.declared_at where parent_id=actor and terms_version=proof.terms_version; end if;
 end if;
 update private.parent_registration_proofs set consumed_at=t,consumed_parent_hash=actor_hash where nonce_hash=p_nonce_hash;
 return jsonb_build_object('completed',true);
end $$;
